response:
{
  "id": "quick-sort-lecture",
  "title": "快速排序",
  "subtitle": "分治、基准与工程权衡",
  "language": "zh-CN",
  "audience": "计算机专业本科生或算法初学者",
  "theme": "lab",
  "tutor": {
    "suggestions": [
      "为什么随机化基准能避免最坏情况？",
      "三路快排相比双路快排，在什么场景下优势最大？",
      "快排的递归栈深度最坏是多少，尾递归优化如何减小它？",
      "归并排序是稳定的，为什么快排做不到？"
    ],
    "kb": [
      {
        "pattern": "分区|Partition",
        "answer": "将数组分为小于基准、大于基准两部分的核心操作，是快排的物理引擎"
      },
      {
        "pattern": "三数取中|Median-of-Three",
        "answer": "取首、中、尾三元素的中位数作为基准，防止已排序数组导致 O(n²) 退化"
      },
      {
        "pattern": "三路快排|3-way QuickSort|荷兰国旗",
        "answer": "将数组分为小于、等于、大于基准三部分，专门处理大量重复元素，消除重复项的无效分区"
      },
      {
        "pattern": "不稳定性|Unstable",
        "answer": "相等元素的相对顺序在排序后可能改变，由长距离交换（如 Hoare 跨越式交换）导致"
      },
      {
        "pattern": "Hoare 分区|双指针",
        "answer": "左右指针相向移动并交换逆序对，比 Lomuto 交换次数少，但边界条件易错"
      }
    ]
  },
  "scenes": [
    {
      "id": "cover",
      "kind": "hero",
      "notes": "开场定调：快排是工程界最常用的排序算法，它的美在于分治思想的极致体现与对现实数据的工程权衡。点出课题，不展开细节。",
      "blocks": [
        {
          "id": "b_cover",
          "type": "hero",
          "intent": "封面：标题+一句副题",
          "size": "xl"
        }
      ]
    },
    {
      "id": "intuition",
      "kind": "content",
      "eyebrow": "核心思想",
      "headline": "分而治之：选标杆与分队",
      "lead": "把比基准小的扔左边，大的扔右边，递归处理两边即完成排序。",
      "notes": "用排队比喻：选一个人当标杆，比他矮的站左边，高的站右边。强调" 							, "基准归位"		: "不管左右多乱，基准这个元素已经到了它最终该在的位置。这是递归能收敛的根本保证。",
      "blocks": [
        {
          "id": "b1",
          "type": "list",
          "intent": "用排队比喻解释分区动作：选标杆、左右分队、原地交换",
          "size": "m"
        },
        {
          "id": "b2",
          "type": "callout",
          "intent": "解答疑问：为什么随便选个基准最终也能排好序？因为每次分区至少把基准放到了最终正确位置",
          "size": "s"
        }
      ]
    },
    {
      "id": "partition-sim",
      "kind": "content",
      "eyebrow": "难点拆解",
      "headline": "原地分区的微观机制",
      "lead": "左右指针相向而行，遇反则交换，直到相遇确认基准落点。",
      "transition": "zoom",
      "notes": "这是全课最难的微观机制。让学生动手拖动进度条，观察左右指针如何移动、何时交换。特别提醒注意 Hoare 分区中指针相遇的边界条件，这是手写快排最容易写出死循环的地方。对比 Lomuto 的单指针扫描，体会 Hoare 为何交换次数更少。",
      "blocks": [
        {
          "id": "bw",
          "type": "sim",
          "engine": "widget",
          "intent": "交互演示 Hoare/Lomuto 分区过程：指针移动、元素交换、基准归位",
          "size": "xl"
        }
      ]
    },
    {
      "id": "complexity",
      "kind": "content",
      "eyebrow": "理论推导",
      "headline": "性能边界：从 $O(n \\log n)$ 到 $O(n^2)$",
      "lead": "递归树的深度与每层工作量决定了时间复杂度，最坏情况发生在极度不平衡的划分。",
      "notes": "画递归树解释：最好情况树是平衡的，每层工作量 O(n)，共 log n 层；最坏情况树退化成链表，第 k 层工作量 n-k。强调空间复杂度 O(log n) 是系统调用栈的开销，不是额外开的数组。平均复杂度 O(n log n) 的直觉：随机选基准相当于树高期望为 log n。",
      "blocks": [
        {
          "id": "b3",
          "type": "formula",
          "intent": "最好/最坏情况递推式 $T(n) = 2T(n/2) + O(n)$ 与 $T(n) = T(n-1) + O(n)$",
          "size": "m"
        },
        {
          "id": "b4",
          "type": "chart",
          "intent": "对比 n log n 与 n² 的增长曲线，直观展示最坏情况的灾难性",
          "size": "l"
        },
        {
          "id": "b5",
          "type": "callout",
          "intent": "解答疑问：原地排序为何空间复杂度不是 O(1)？因为递归调用栈的深度",
          "size": "s"
        }
      ]
    },
    {
      "id": "engineering",
      "kind": "content",
      "eyebrow": "工程实践",
      "headline": "工业界的不退化和防内耗",
      "lead": "标准库的快排并非纯快排，而是针对现实数据特征的多重补丁组合。",
      "notes": "工业界不用教科书式的纯快排。讲三数取中防手抖，讲小数组切插入是因为 n<15 时递归开销比 O(n²) 的插入排序常数还大。重点讲三路快排，这是解决" 	, "全相同元素退化"	: "的杀手锏，把等于区直接跳过。",
      "blocks": [
        {
          "id": "b6",
          "type": "agenda",
          "intent": "列举三大工程优化：三数取中防退化、小数组切插入排序、三路快排处理大量重复",
          "size": "m"
        },
        {
          "id": "b7",
          "type": "diagram",
          "intent": "三路快排（荷兰国旗）结构：小于区 | 等于区 | 大于区",
          "size": "m"
        }
      ]
    },
    {
      "id": "comparison",
      "kind": "content",
      "eyebrow": "横向对比",
      "headline": "与归并排序的镜像与倒影",
      "lead": "同为分治，快排胜在原地与缓存友好，败在不稳定与最坏退化。",
      "notes": "与归并对比，快排胜在原地（不用额外 O(n) 数组）和缓存友好（顺序扫描），败在不稳定。用一个具体反例（如 [3, 2, 2']）演示交换如何破坏稳定性。解释为什么标准库更偏爱快排：平均快、省内存、优化空间大。",
      "blocks": [
        {
          "id": "b8",
          "type": "compare",
          "intent": "快排 vs 归并：时间复杂度下限、空间占用、稳定性、缓存命中率对比",
          "size": "l"
        },
        {
          "id": "b9",
          "type": "callout",
          "intent": "快排不稳定性证明：给出具体反例 [3, 2, 2']，展示交换如何改变相等元素的相对顺序",
          "size": "s"
        }
      ]
    },
    {
      "id": "quiz",
      "kind": "quiz",
      "headline": "随堂检验",
      "notes": "通过两个客观题检验学生对最坏情况触发条件及三路快排优势的理解，确保核心概念没有遗漏。",
      "blocks": [
        {
          "id": "bq",
          "type": "quiz",
          "intent": "考察对最坏情况触发条件及三路快排优势的理解",
          "size": "m"
        }
      ]
    },
    {
      "id": "ending",
      "kind": "hero",
      "notes": "收尾总结：快排的" 	, "快"	: "不是数学上的最坏最快，而是平均表现和工程优化的综合胜利。从直觉到工程，这是算法演化的典型路径。",
      "blocks": [
        {
          "id": "b_ending",
          "type": "hero",
          "intent": "收尾：总结快排从直觉到工程的演化",
          "size": "xl"
        }
      ]
    }
  ]
}
